property.default:
html, body {
    margin:0;
    padding:0;
    width:100%;
    height:100%;
    overflow:hidden;
}

#player {
    position:absolute;
    top:0;
    left:0;
    width:100%;
    height:100%;
}

module.onInitialize:
// id: The id of the widget
// target: The target element to render
// properties: The properties for the widget
// -------------------------------------------
// EmbedInit()는 embedJavaScript 안에서 사용자가 정의할 수 있는 함수
// 사용자 정의 초기화 함수가 있으면 실행
if(typeof EmbedInit === 'function') {
    EmbedInit();
}

module.onRender:
// scaleContent가 체크된 경우 레이아웃 스케일러 적용
// properties.scaleContent: widgetoption 테이블에서 로드된 값 (0 또는 1)
if(properties.scaleContent) {
    window.scaleContent = true;
    // globalOptions: 레이아웃 너비/높이/스케일 정보를 담은 전역 객체
    $(target).xiboLayoutScaler(globalOptions);
}
